package review

import "testing"

func TestReviewContract(t *testing.T) {
	if _, err := Parse("{\"summary\":\"clean\",\"findings\":[]}"); err != nil { t.Fatal(err) }
	for _, raw := range []string{"not JSON", "{\"summary\":\"clean\"}", "{\"summary\":\"clean\",\"findings\":null}"} {
		if _, err := Parse(raw); err == nil { t.Fatalf("accepted %s", raw) }
	}
	result, err := Parse("{\"summary\":\"risk\",\"findings\":[{\"category\":\"performance\",\"confidence\":\"confirmed\"}]}")
	if err != nil { t.Fatal(err) }
	expected := Finding{Category:"performance", Confidence:"needs_verification"}
	if result.Findings[0].Confidence != expected.Confidence || Overconfirmed(result.Findings[0], expected) { t.Fatal("policy mismatch") }
}

